const menuGroupAt={0:'🧰 نگهداری و نسخه',3:'🔌 اتصال‌ها و سرویس‌ها',7:'📦 عملیات محصولات و سلامت',16:'🤖 اتوماسیون و گزارش'};
function initMenu(){$('menuSections').innerHTML='<div class="drawer-guide"><b>ابزارهای تکمیلی</b>کارهای اصلی در شش بخش پایین صفحه‌اند. اینجا فقط تنظیمات تخصصی و عملیات نگهداری، براساس موضوع گروه‌بندی شده‌اند.</div>'+menuDefs.map(([title,key,desc,content],index)=>(menuGroupAt[index]?'<div class="menu-group-label">'+menuGroupAt[index]+'</div>':'')+'<section class="menu-section" data-menu="'+key+'"><button class="menu-title"><span>'+title+'</span><i>▼</i></button><div class="menu-content"><details class="menu-desc"><summary>ℹ️ توضیح این بخش</summary><p class="menu-text">'+desc+'</p></details>'+content+'</div></section>').join('');renderThemeSwatches()}
function initFields(){ $('selectorGrid').innerHTML=listFields.map(([id,label])=>fieldHtml(id,label,id==='container'?'li.product':id==='title'?'h2':id==='price'?'.price':id==='link'?'a[href]':'img')).join(''); $('detailGrid').innerHTML=detailFields.map(([id,label])=>fieldHtml(id,label,'')).join('');galModeChanged();updateDetailSummary();initAutoSave() }
function galModeChanged(){const mode=$('galMode').value;$('galAutoBox').hidden=mode!=='auto';$('galManualBox').hidden=mode!=='manual';$('galNumberBox').hidden=mode!=='number';$('galCommon').hidden=mode==='off'||mode==='variations'?mode==='off':false;if($('detailSelectionSummary'))updateDetailSummary()}
