  const ai=state.connections?.ai||{},only=Boolean($('aiTestOnlyUntested')?.checked),providers=(ai.providers||[]).filter(p=>p.enabled!==false),candidates=new Set(Array.isArray(ai.candidates)?ai.candidates.map(String):[]);
