 for(const name of Object.keys(filtered))encoded[name]=settingsEncodeFile(filtered[name]);
 const payload={...bundle,files:encoded,total_files:Object.keys(encoded).length,total_bytes:Object.values(encoded).reduce((sum,x)=>sum+(x.size||0),0)};
