 a.href=url;a.download=name;a.rel='noopener';a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),400);
 if(status)status.textContent='✅ برون‌ریزی شد: '+name+' ('+fa(Object.keys(encoded).length)+' بخش)';
