function selectableCategoryOptions(){if(!categoryManager)return[];const leaves=categoryManager.categories.filter(item=>item.leaf!==false);return leaves.length?leaves:categoryManager.categories}
function categoryOptions(query=''){if(!categoryManager)return;const normalized=String(query).trim().toLowerCase(),select=$('categorySelect'),before=select.value,items=selectableCategoryOptions().filter(item=>!normalized||String(item.name+' '+item.path+' '+item.id).toLowerCase().includes(normalized)).slice(0,500);select.innerHTML=items.map(item=>'<option value="'+item.id+'">'+esc((item.path||item.name)+' (#'+item.id+')')+'</option>').join('')||'<option value="">نتیجه‌ای پیدا نشد</option>';if(items.some(item=>String(item.id)===before))select.value=before}
function renderCategoryPlan(){if(!categoryManager)return;const box=$('categoryPlan'),valid=categoryManager.plan.filter(row=>row.categoryId>0),categories=selectableCategoryOptions();box.innerHTML=categoryManager.plan.length?categoryManager.plan.map((row,index)=>{const options='<option value="">— انتخاب اصلاح دستی —</option>'+categories.map(item=>'<option value="'+item.id+'"'+(Number(item.id)===Number(row.categoryId)?' selected':'')+'>'+esc((item.path||item.name)+' (#'+item.id+')')+'</option>').join('');return'<div class="category-plan-row '+(row.categoryId?'ok':'bad')+'"><b>'+esc(row.title)+'</b><br>'+(row.categoryId?'🏷 '+esc(row.categoryName)+' (#'+fa(row.categoryId)+')':'بدون پیشنهاد معتبر')+'<br><span style="color:#94a3b8">منبع: '+esc(row.source||'—')+(row.confidence?' · اطمینان: '+fa(row.confidence)+'٪':'')+'</span><div class="field" style="margin-top:7px"><label>اصلاح دستی پیشنهاد این محصول</label><select data-category-row="'+index+'">'+options+'</select></div>'+(row.alternatives?.length?'<details><summary>پاسخ مدل‌ها</summary>'+row.alternatives.map(x=>'<div>'+esc(x.model)+': '+(x.ok?esc(x.categoryName)+' (#'+fa(x.categoryId)+')':'خطا — '+esc(x.error||''))+'</div>').join('')+'</details>':'')+'</div>'}).join(''):'<div class="empty compact">هنوز پیش‌نمایش دسته ساخته نشده است.</div>';$('categoryPreviewApply').disabled=!valid.length;$('categoryApply').disabled=true;$('categoryPreview').innerHTML='';categoryManager.previewed=false}
async function openDestinationCategoryManager(products){
  if(dest.target!=='basalam')throw Error('مدیریت دسته‌بندی این بخش مخصوص محصولات باسلام است.');products=(products||[]).filter(Boolean).slice(0,20);if(!products.length)throw Error('ابتدا محصول را انتخاب کنید.');modalShell('🏷 مدیریت دسته‌بندی باسلام','<div class="empty">در حال دریافت فهرست دسته‌بندی باسلام…</div>');
  try{const[data,lastTest]=await Promise.all([api('/api/categories/basalam'),api('/api/ai/test-results').catch(()=>({results:[]}))]),models=destinationAiModels(lastTest);categoryManager={products,categories:Array.isArray(data.items)?data.items:[],models,plan:[],previewed:false};const modelHtml=models.length?models.map((item,index)=>'<label><input type="checkbox" data-category-model value="'+escAttr(item.key)+'" '+(item.preferred?'checked':'')+'><span>'+esc(item.provider)+' · '+esc(item.model)+'</span></label>').join(''):'<div class="help-box">در آخرین اجرای تست مدل‌ها هیچ مدل سبزی ثبت نشده است؛ ابتدا از منوی هوش مصنوعی ← تست مدل‌ها یک اجرای موفق انجام دهید.</div>';modalShell('🏷 مدیریت دسته‌بندی '+(products.length===1?'تکی':'گروهی')+' باسلام','<div class="result-summary ok">'+fa(products.length)+' محصول انتخاب شده است. ابتدا یکی از سه روش را اجرا کنید، سپس پیش‌نمایش واقعی API و در پایان اعمال را بزنید.</div><h3>۱) روش دستی</h3><div class="row"><div class="field"><label>جست‌وجوی دستهٔ باسلام</label><input id="categorySearch" placeholder="نام یا شناسه دسته…"></div><div class="field"><label>انتخاب دسته</label><select id="categorySelect"></select></div></div><button class="btn btn-yellow" data-category-action="manual">ساخت پیشنهاد دستی</button><h3 style="margin-top:15px">۲) روش نیمه‌هوشمند</h3><p class="field-hint">از دسته‌هایی که پس از ویرایش‌های قبلی در D1 آموخته شده‌اند استفاده می‌کند.</p><button class="btn btn-purple" data-category-action="learned">پیشنهاد از آموخته‌های قبلی</button><h3 style="margin-top:15px">۳) روش هوشمند با مدل‌های انتخابی</h3><div class="category-models">'+modelHtml+'</div><p class="field-hint">حداکثر ۵ مدل؛ برای هر محصول رأی مدل‌ها اعتبارسنجی و نتیجهٔ اکثریت انتخاب می‌شود.</p><button class="btn btn-blue" data-category-action="ai" '+(models.length?'':'disabled')+'>تحلیل با مدل‌های انتخاب‌شده</button><div id="categoryProgress" class="field-hint"></div><h3 style="margin-top:15px">برنامهٔ پیشنهادی</h3><div id="categoryPlan" class="category-plan"></div><div id="categoryPreview"></div><div class="bulk-actions"><button id="categoryPreviewApply" class="btn btn-purple" data-category-action="preview" disabled>👁 پیش‌نمایش واقعی API</button><button id="categoryApply" class="btn btn-green" data-category-action="apply" disabled>✓ اعمال دسته‌بندی‌ها</button></div>');categoryOptions();renderCategoryPlan();const root=$('resultModal'),baseClick=root.onclick;root.onclick=e=>{const action=e.target.closest('[data-category-action]');if(action){runCategoryAction(action.dataset.categoryAction,action).catch(error=>{categoryManager&&(categoryManager.previewed=false);const status=$('categoryProgress');if(status)status.textContent='خطا: '+error.message;notice(error.message,'error')});return}baseClick(e)};root.oninput=e=>{if(e.target.id==='categorySearch')categoryOptions(e.target.value)};root.onchange=e=>{const select=e.target.closest('[data-category-row]');if(!select||!categoryManager)return;const index=Number(select.dataset.categoryRow),category=categoryManager.categories.find(item=>String(item.id)===select.value),row=categoryManager.plan[index];if(!row||!category)return;categoryManager.plan[index]={...row,categoryId:Number(category.id),categoryName:String(category.name),source:'اصلاح دستی',confidence:100};renderCategoryPlan()}}catch(error){openResultModal('⚠️ خطای فهرست دسته‌بندی',{ok:false,error:error.message,recommendations:['اتصال و توکن باسلام را در منوی ارتباط‌ها بررسی کنید.']})}
}
function categoryAssignments(){return(categoryManager?.plan||[]).filter(row=>row.categoryId>0).map(row=>({id:row.id,shopId:row.shopId,categoryId:row.categoryId,categoryName:row.categoryName,source:row.source}))}
async function runCategoryAction(action,button){if(!categoryManager)return;const progress=$('categoryProgress');
  if(action==='manual'){const category=categoryManager.categories.find(item=>String(item.id)===$('categorySelect').value);if(!category)throw Error('یک دستهٔ معتبر باسلام انتخاب کنید.');categoryManager.plan=categoryManager.products.map(product=>({id:product.id,shopId:product.shopId,title:product.title,categoryId:category.id,categoryName:category.name,source:'دستی',confidence:100}));renderCategoryPlan();return}
  if(action==='learned'){busy(button,true);try{progress.textContent='در حال بررسی آموخته‌های قبلی…';const rows=await Promise.all(categoryManager.products.map(async product=>{const data=await api('/api/destination/basalam/category/suggest',{method:'POST',body:JSON.stringify({mode:'learned',title:product.title})}),found=data.result;return{id:product.id,shopId:product.shopId,title:product.title,categoryId:Number(found?.categoryId)||0,categoryName:found?.categoryName||'',source:found?'آموخته: '+found.phrase+' ('+fa(found.hits)+' بار)':'آموخته‌ای پیدا نشد',confidence:found?Math.min(99,60+Number(found.hits||0)*5):0}}));categoryManager.plan=rows;renderCategoryPlan();progress.textContent='آموخته‌ها بررسی شدند؛ '+fa(rows.filter(x=>x.categoryId).length)+' پیشنهاد معتبر.'}finally{busy(button,false)}return}
  if(action==='ai'){const modelKeys=[...document.querySelectorAll('[data-category-model]:checked')].map(x=>x.value);if(!modelKeys.length)throw Error('حداقل یک مدل را انتخاب کنید.');if(modelKeys.length>5)throw Error('برای کنترل زمان و درخواست‌ها حداکثر ۵ مدل انتخاب کنید.');busy(button,true);try{const modelName=key=>categoryManager.models.find(x=>x.key===key)?.model||key,threshold=Math.floor(modelKeys.length/2)+1,plan=[];
    for(let i=0;i<categoryManager.products.length;i++){
      const product=categoryManager.products[i];
      progress.textContent='تحلیل محصول '+fa(i+1)+' از '+fa(categoryManager.products.length)+' با '+fa(modelKeys.length)+' مدل…';
      const currentCategory=Number(product.categoryId||product.category_id||product.raw?.category_id)||0;
      let tried=new Set();
      try{const t=await api('/api/destination/basalam/category-tried?shopId='+encodeURIComponent(String(product.shopId||''))+'&id='+product.id);tried=new Set((t.tried||[]).map(Number))}catch{}
      const votes=new Map(),alternatives=[];let responded=0,validIds=[];
      for(const key of modelKeys){
        let suggestion;
        try{suggestion=await api('/api/destination/basalam/category/suggest',{method:'POST',body:JSON.stringify({mode:'ai',title:product.title,modelKey:key})})}catch(error){suggestion={ok:false,key,error:error.message}}
        responded++;alternatives.push({ok:Boolean(suggestion.ok),model:modelName(key),categoryId:suggestion.categoryId,categoryName:suggestion.categoryName,error:suggestion.error});
        if(!suggestion.ok)continue;
        const id=Number(suggestion.categoryId);if(!(Number.isInteger(id)&&id>0))continue;
        if(tried.has(id))continue;
        validIds.push(id);
        const vote=votes.get(id)||{count:0,row:suggestion};vote.count++;votes.set(id,vote);
        // Early stop: majority reached → stop asking the remaining models.
        if(vote.count>=threshold)break;
      }
      const winner=[...votes.values()].sort((a,b)=>b.count-a.count)[0],rowBase={id:product.id,shopId:product.shopId,title:product.title,alternatives};
      if(winner&&currentCategory&&Number(winner.row.categoryId)===currentCategory)plan.push({...rowBase,categoryId:currentCategory,categoryName:String(winner.row.categoryName||''),source:'دستهٔ فعلی تأیید شد (بدون تغییر)',confidence:responded?Math.round(winner.count/responded*100):0});
      else if(winner)plan.push({...rowBase,categoryId:Number(winner.row.categoryId),categoryName:String(winner.row.categoryName||''),source:'هوش مصنوعی: '+winner.count+' از '+responded+' رأی',confidence:responded?Math.round(winner.count/responded*100):0});
      else{
        // No majority: remember every suggested category for this product so the next
        // run skips them and the models focus on untried options (faster convergence).
        if(validIds.length)try{await api('/api/destination/basalam/category-tried',{method:'POST',body:JSON.stringify({shopId:String(product.shopId||''),id:product.id,ids:validIds})})}catch{}
        plan.push({...rowBase,categoryId:0,categoryName:'',source:validIds.length?'پیشنهادها بدون اکثریت؛ گزینه‌های امتحان‌شده برای دفعهٔ بعد ذخیره شدند':'پاسخ معتبر دریافت نشد',confidence:0});
      }
    }
    categoryManager.plan=plan;renderCategoryPlan();progress.textContent='تحلیل هوشمند تمام شد؛ '+fa(plan.filter(x=>x.categoryId).length)+' پیشنهاد معتبر.'}finally{busy(button,false)}return}
  const assignments=categoryAssignments();if(!assignments.length)throw Error('هیچ پیشنهاد معتبری برای پیش‌نمایش وجود ندارد.');const body={ids:categoryManager.products.map(x=>({id:x.id,shopId:x.shopId})),ops:{categoryAssignments:assignments}};
  if(action==='preview'){busy(button,true);try{const data=await api('/api/destination/basalam/bulk',{method:'POST',body:JSON.stringify(body)});categoryManager.previewed=Boolean(data.dryRun)&&!data.failed;$('categoryPreview').innerHTML='<div class="result-summary '+(categoryManager.previewed?'ok':'bad')+'"><b>پیش‌نمایش API: '+(categoryManager.previewed?'آمادهٔ اعمال':'نیازمند بررسی')+'</b><br>تغییر: '+fa(data.changed)+' · خطا: '+fa(data.failed)+' · بدون تغییر: '+fa(data.skipped)+'</div>';$('categoryApply').disabled=!categoryManager.previewed;output(data)}finally{busy(button,false)}return}
  if(action==='apply'){if(!categoryManager.previewed)throw Error('ابتدا پیش‌نمایش واقعی API را اجرا کنید.');if(!confirm('دسته‌بندی '+assignments.length+' محصول واقعاً در باسلام تغییر کند؟'))return;body.confirm='APPLY';busy(button,true);try{const data=await api('/api/destination/basalam/bulk',{method:'POST',body:JSON.stringify(body)});openResultModal('✓ نتیجهٔ اعمال دسته‌بندی باسلام',{...data,raw:data.items,recommendations:data.failed?['محصولات خطادار را بررسی و دوباره اجرا کنید.']:['دسته‌ها اعمال و برای پیشنهادهای نیمه‌هوشمند آینده آموخته شدند.']});dest.selected.clear();await loadDestination(true)}finally{busy(button,false)}}
}
function destinationStatuses(target=dest.target){return target==='woo'?[['all','همه'],['publish','منتشرشده'],['draft','پیش‌نویس'],['pending','در انتظار'],['private','خصوصی'],['trash','زباله‌دان']]:[['all','همه'],['2976','فعال'],['3790','غیرفعال'],['3567','تأیید نشده'],['3568','در انتظار تأیید'],['4184','بایگانی']]}
function destinationKey(product){return String(product.shopId||'default')+':'+String(product.id)}
function destinationRefs(){return [...dest.selected.values()].map(x=>({id:Number(x.id),shopId:String(x.shopId||'')}))}
function destinationStatusOptions(selected,blank=false){return (blank?'<option value="">بدون تغییر</option>':'')+destinationStatuses().filter(x=>x[0]!=='all').map(x=>'<option value="'+escAttr(x[0])+'"'+(String(selected)===String(x[0])?' selected':'')+'>'+esc(x[1])+'</option>').join('')}
async function openDestinationManager(mode='woo'){const unapproved=mode==='basalam-unapproved',target=mode==='woo'?'woo':'basalam',modal=$('destinationManagerModal');modal.hidden=false;document.body.style.overflow='hidden';$('destinationManagerTitle').textContent=target==='woo'?'🛒 مدیریت محصولات ووکامرس':unapproved?'🟠 تصحیح محصولات تأییدنشدهٔ باسلام':'🏪 مدیریت محصولات باسلام';setDestinationTarget(target,false);dest.status=unapproved?'3567':'all';renderDestinationStatuses();await loadDestination(true)}
function closeDestinationManager(){$('destinationManagerModal').hidden=true;document.body.style.overflow=''}
function setDestinationView(view){dest.view=view==='rows'?'rows':'cards';renderDestination()}
function selectDestinationPage(selected=true){if(selected)dest.selected.clear();for(const product of dest.products.slice(0,20)){const key=destinationKey(product);if(selected)dest.selected.set(key,product);else dest.selected.delete(key)}renderDestination()}
function updateDestinationSelection(){const count=dest.selected.size;$('destSelection').textContent=fa(count)+' انتخاب';$('destBulkCount').textContent='('+fa(count)+' محصول)';document.querySelectorAll('[data-dest-key],[data-dest-row]').forEach(row=>row.classList.toggle('selected',Boolean(row.querySelector('.dest-check')?.checked)));const selectable=dest.products.map(destinationKey),selectedHere=selectable.filter(key=>dest.selected.has(key)).length,all=$('destSelectAll');if(all){all.checked=Boolean(selectable.length)&&selectedHere===selectable.length;all.indeterminate=selectedHere>0&&selectedHere<selectable.length}}
function setDestinationTarget(target,load=false){dest.target=target==='basalam'?'basalam':'woo';dest.page=1;dest.status='all';dest.products=[];dest.counts={};dest.selected.clear();document.querySelectorAll('[data-dest-target]').forEach(x=>x.classList.toggle('active',x.dataset.destTarget===dest.target));$('destShop').disabled=dest.target==='woo';$('destShop').innerHTML=dest.target==='woo'?'<option value="default">فروشگاه ووکامرس</option>':'<option value="all">همهٔ غرفه‌ها</option>';$('destBulkStatus').innerHTML=destinationStatusOptions('',true);$('destBulkCategory').hidden=dest.target!=='basalam';$('destUnapprovedTools').hidden=true;renderDestinationStatuses();renderDestination();updateDestinationSelection();if(load)loadDestination(true)}
function renderDestinationStatuses(){const counts=dest.counts||{};$('destUnapprovedTools').hidden=!(dest.target==='basalam'&&dest.status==='3567');$('destStatusPills').innerHTML=destinationStatuses().map(x=>'<button class="status-pill '+(dest.status===x[0]?'active':'')+'" data-dest-status="'+escAttr(x[0])+'">'+esc(x[1])+(counts[x[0]]!==undefined?'<b>'+fa(counts[x[0]])+'</b>':'')+'</button>').join('')}
function destinationActions(product,key){return'<div class="dest-actions"><button class="btn btn-blue btn-sm" data-dest-action="edit" data-key="'+escAttr(key)+'">✎ جزئیات و ویرایش</button>'+(dest.target==='basalam'?'<button class="btn btn-yellow btn-sm" data-dest-action="category" data-key="'+escAttr(key)+'">🏷 دسته‌بندی</button>':'')+'<select class="btn btn-gray btn-sm" data-dest-card-status="'+escAttr(key)+'">'+destinationStatusOptions(product.status)+'</select><button class="btn btn-green btn-sm" data-dest-action="status" data-key="'+escAttr(key)+'">✓ وضعیت</button><button class="btn btn-red btn-sm" data-dest-action="delete" data-key="'+escAttr(key)+'">'+(dest.target==='basalam'?'بایگانی':'حذف')+'</button></div>'}
function destinationTable(){const shopHead=dest.target==='basalam'?'<th>غرفه</th>':'',rows=dest.products.map(product=>{const key=destinationKey(product),selected=dest.selected.has(key),image=product.image?'<img class="dest-table-image" loading="lazy" src="'+escAttr(product.image)+'" alt="">':'<div class="dest-table-image dest-table-empty-image">▧</div>',reject=product.rejectionReason?'<div class="dest-reject">'+esc(product.rejectionReason)+'</div>':'';return'<tr data-dest-row="'+escAttr(key)+'" class="'+(selected?'selected':'')+'"><td class="dest-table-check"><input class="dest-check" type="checkbox" data-dest-select="'+escAttr(key)+'" '+(selected?'checked':'')+' aria-label="انتخاب محصول"></td><td>'+image+'</td><td class="dest-table-title">'+esc(product.title||'بدون عنوان')+'<small>#'+esc(product.id)+(product.sku?' · SKU: '+esc(product.sku):'')+'</small></td><td class="dest-table-price">'+fa(product.price)+' تومان</td><td class="dest-table-meta">'+esc(product.statusLabel||product.status||'—')+reject+'</td><td class="dest-table-meta">'+(product.stock===null?'نامشخص':fa(product.stock))+'</td><td class="dest-table-meta">'+esc(product.category||'—')+'</td>'+(dest.target==='basalam'?'<td class="dest-table-meta">'+esc(product.shopName||product.shopId||'—')+'</td>':'')+'<td class="dest-table-actions">'+destinationActions(product,key)+'</td></tr>'}).join('');return'<table class="dest-table"><thead><tr><th class="dest-table-check">انتخاب</th><th>تصویر</th><th>محصول / شناسه</th><th>قیمت</th><th>وضعیت</th><th>موجودی</th><th>دسته</th>'+shopHead+'<th>عملیات</th></tr></thead><tbody>'+rows+'</tbody></table>'}
function renderDestination(){const box=$('destProducts');box.classList.toggle('dest-view-rows',dest.view==='rows');document.querySelectorAll('[data-dest-view]').forEach(button=>button.classList.toggle('active',button.dataset.destView===dest.view));if(!dest.products.length){box.innerHTML='<div class="empty">'+(dest.total?'در این صفحه محصولی نیست.':'محصولی یافت نشد؛ اتصال، غرفه و فیلتر را بررسی کنید.')+'</div>'}else if(dest.view==='rows')box.innerHTML=destinationTable();else box.innerHTML=dest.products.map(p=>{const key=destinationKey(p),checked=dest.selected.has(key),meta=['#'+fa(p.id),p.sku?'SKU: '+p.sku:'',p.category||'',dest.target==='basalam'?(p.shopName||p.shopId):''].filter(Boolean).join(' · ');return '<article class="dest-product '+(checked?'selected':'')+'" data-dest-key="'+escAttr(key)+'"><input class="dest-check" type="checkbox" data-dest-select="'+escAttr(key)+'" '+(checked?'checked':'')+' aria-label="انتخاب محصول">'+(p.image?'<img class="dest-image" loading="lazy" src="'+escAttr(p.image)+'" alt="">':'<div class="dest-image" style="display:grid;place-items:center;color:#64748b">بدون تصویر</div>')+'<div><div class="dest-title">'+esc(p.title||'بدون عنوان')+'</div><div class="dest-price">'+fa(p.price)+' تومان</div><div class="dest-meta">'+esc(meta)+'<br>موجودی: '+(p.stock===null?'نامشخص':fa(p.stock))+' · وضعیت: '+esc(p.statusLabel||p.status||'—')+'</div>'+(p.rejectionReason?'<div class="dest-reject">'+esc(p.rejectionReason)+'</div>':'')+destinationActions(p,key)+'</div></article>'}).join('');$('destSummary').textContent=fa(dest.total)+' محصول · صفحه '+fa(dest.page)+' از '+fa(dest.totalPages);$('destPageInfo').textContent='صفحه '+fa(dest.page)+' از '+fa(dest.totalPages);$('destPrev').disabled=dest.page<=1;$('destNext').disabled=dest.page>=dest.totalPages;updateDestinationSelection()}
async function loadDestination(withCounts=true){const button=$('destLoad');busy(button,true);$('destProducts').innerHTML='<div class="dest-loading">در حال دریافت مستقیم محصولات '+(dest.target==='woo'?'ووکامرس':'باسلام')+'…</div>';try{const query=new URLSearchParams({page:String(dest.page),per_page:$('destPerPage').value,q:$('destSearch').value.trim(),status:dest.status,shop:$('destShop').value||'all',counts:withCounts?'1':'0'}),data=await api('/api/destination/'+dest.target+'/products?'+query.toString());dest.products=Array.isArray(data.items)?data.items:[];dest.total=Number(data.total||0);dest.totalPages=Math.max(1,Number(data.totalPages||1));dest.page=Math.min(dest.page,dest.totalPages);if(data.counts)dest.counts=data.counts;dest.shops=Array.isArray(data.shops)?data.shops:[];if(dest.target==='basalam'){const current=$('destShop').value||'all';$('destShop').innerHTML='<option value="all">همهٔ غرفه‌ها</option>'+dest.shops.map(s=>'<option value="'+escAttr(s.id)+'">'+esc(s.name)+(s.primary?' · پیش‌فرض':'')+'</option>').join('');if([...$('destShop').options].some(x=>x.value===current))$('destShop').value=current}$('destBulkStatus').innerHTML=destinationStatusOptions('',true);renderDestinationStatuses();renderDestination();notice(fa(dest.total)+' محصول از مقصد دریافت شد.','ok')}catch(error){dest.products=[];dest.total=0;$('destProducts').innerHTML='<div class="empty">❌ '+esc(error.message)+'<br><small>ابتدا اتصال مقصد را از منوی کناری آزمایش کنید.</small></div>';notice(error.message,'error');openResultModal('⚠️ خطای دریافت محصولات مقصد',{ok:false,target:dest.target,error:error.message,recommendations:['اتصال مقصد و شناسه غرفه را آزمایش کنید.','در باسلام مطمئن شوید توکن به همین غرفه دسترسی دارد.','متن HTTP نمایش‌داده‌شده را برای تشخیص endpoint بررسی کنید.']})}finally{busy(button,false)}}
function destinationProductByKey(key){return dest.products.find(p=>destinationKey(p)===key)||dest.selected.get(key)}
async function destinationCardAction(action,key){const product=destinationProductByKey(key);if(!product)throw Error('محصول در فهرست فعلی پیدا نشد.');if(action==='edit')return openDestinationEditor(product);if(action==='category')return openDestinationCategoryManager([product]);if(action==='status'){const select=document.querySelector('[data-dest-card-status="'+CSS.escape(key)+'"]'),status=select?.value;if(!status)throw Error('وضعیت را انتخاب کنید.');if(!confirm('وضعیت «'+product.title+'» تغییر کند؟'))return;const d=await api('/api/destination/'+dest.target+'/'+product.id+'/status',{method:'POST',body:JSON.stringify({status,shopId:product.shopId,confirm:'APPLY'})});openResultModal('✓ تغییر وضعیت محصول',d);await loadDestination(true);return}if(action==='delete')return deleteDestinationProduct(product)}
async function deleteDestinationProduct(product){const verb=dest.target==='basalam'?'بایگانی شود؟ این عمل به وضعیت ۴۱۸۴ تغییر می‌کند و حذف دائمی نیست.':'به زباله‌دان منتقل شود؟';if(!confirm('محصول «'+product.title+'» '+verb))return;const d=await api('/api/destination/'+dest.target+'/'+product.id+'?confirm=DELETE&shop='+encodeURIComponent(product.shopId||'')+'&force=false',{method:'DELETE'});dest.selected.delete(destinationKey(product));openResultModal(dest.target==='basalam'?'🗄 نتیجه بایگانی باسلام':'🗑 نتیجه حذف ووکامرس',{...d,recommendations:dest.target==='basalam'?['API باسلام حذف دائمی ندارد؛ محصول با وضعیت ۴۱۸۴ بایگانی شد.']:['محصول به زباله‌دان ووکامرس منتقل شد و در صورت نیاز قابل بازیابی است.']});await loadDestination(true)}
function destinationEditPayload(product){const body={shopId:product.shopId},title=$('dpTitle').value.trim(),price=$('dpPrice').value,stock=$('dpStock').value,status=$('dpStatus').value,shortDescription=$('dpShort').value,description=$('dpDescription').value,sku=$('dpSku')?.value.trim(),categoryId=$('dpCategory').value;if(title!==product.title)body.title=title;if(price!==''&&Number(price)!==Number(product.price))body.price=Number(price);if(stock!==''&&Number(stock)!==Number(product.stock))body.stock=Number(stock);if(status!==String(product.status))body.status=status;if(shortDescription!==String(product.shortDescription||''))body.shortDescription=shortDescription;if(description!==String(product.description||''))body.description=description;if(dest.target==='woo'&&sku!==String(product.sku||''))body.sku=sku;if(categoryId!==''&&Number(categoryId)!==Number(product.categoryId||0))body.categoryId=Number(categoryId);if(dest.target==='basalam'){for(const id of ['preparation_days','weight','package_weight']){const input=$('dp_'+id);if(input&&input.value!==''&&Number(input.value)!==Number(product.raw?.[id]??product.raw?.revision?.data?.[id]??0))body[id]=Number(input.value)}}return body}
async function openDestinationEditor(summary){modalShell('⏳ دریافت جزئیات محصول','<div class="dest-loading">در حال دریافت اطلاعات کامل محصول…</div>');try{const data=await api('/api/destination/'+dest.target+'/product/'+summary.id+'?shop='+encodeURIComponent(summary.shopId||'')),p=data.product,extra=dest.target==='basalam'?'<div><label>روز آماده‌سازی</label><input id="dp_preparation_days" type="number" min="0" value="'+escAttr(p.raw?.preparation_days??p.raw?.revision?.data?.preparation_days??'')+'"></div><div><label>وزن محصول (گرم)</label><input id="dp_weight" type="number" min="0" value="'+escAttr(p.raw?.weight??p.raw?.revision?.data?.weight??'')+'"></div><div><label>وزن بسته (گرم)</label><input id="dp_package_weight" type="number" min="0" value="'+escAttr(p.raw?.package_weight??p.raw?.revision?.data?.package_weight??'')+'"></div>':'';modalShell('✎ ویرایش '+(dest.target==='woo'?'ووکامرس':'باسلام')+' · #'+fa(p.id),'<p class="modal-note">قیمت در رابط به تومان است. دکمهٔ پیش‌نمایش هیچ تغییری در فروشگاه ایجاد نمی‌کند.</p><div class="inline-form"><div class="wide"><label>عنوان</label><input id="dpTitle" value="'+escAttr(p.title)+'"></div><div><label>قیمت (تومان)</label><input id="dpPrice" type="number" min="0" value="'+escAttr(p.price)+'"></div><div><label>موجودی</label><input id="dpStock" type="number" min="0" value="'+(p.stock===null?'':escAttr(p.stock))+'"></div><div><label>وضعیت</label><select id="dpStatus">'+destinationStatusOptions(p.status)+'</select></div><div><label>SKU</label><input id="dpSku" value="'+escAttr(p.sku||'')+'" '+(dest.target==='basalam'?'disabled':'')+'></div><div><label>شناسه دسته</label><input id="dpCategory" type="number" min="0" value="'+escAttr(p.categoryId||'')+'"></div>'+extra+'<div class="wide"><label>توضیح کوتاه</label><textarea id="dpShort" rows="3">'+esc(p.shortDescription||'')+'</textarea></div><div class="wide"><label>توضیحات کامل</label><textarea id="dpDescription" rows="7">'+esc(p.description||'')+'</textarea></div></div><div id="dpPreview"></div><div class="bulk-actions"><button class="btn btn-purple" data-dp-action="preview">👁 پیش‌نمایش</button><button class="btn btn-green" data-dp-action="apply">✓ اعمال واقعی</button><button class="btn btn-red" data-dp-action="delete">'+(dest.target==='basalam'?'🗄 بایگانی':'🗑 انتقال به زباله‌دان')+'</button></div>');const root=$('resultModal');root.onclick=async event=>{if(event.target===root||event.target.closest('[data-modal-action="close"]'))return root.remove();const button=event.target.closest('[data-dp-action]');if(!button)return;try{const action=button.dataset.dpAction;if(action==='delete'){root.remove();return deleteDestinationProduct(p)}const body=destinationEditPayload(p),apply=action==='apply';if(apply&&!confirm('تغییرات واقعاً روی محصول مقصد اعمال شوند؟'))return;body.confirm=apply?'APPLY':'';busy(button,true);const result=await api('/api/destination/'+dest.target+'/'+p.id+'/update',{method:'POST',body:JSON.stringify(body)});if(apply){openResultModal('✓ نتیجه ویرایش محصول',{...result,raw:result.product||result.changes});await loadDestination(true)}else $('dpPreview').innerHTML='<div class="result-summary '+(result.changed?'ok':'bad')+'"><b>'+(result.changed?'تغییرات قابل اعمال':'تغییری نسبت به مقصد ثبت نشده')+'</b><div class="raw-block">'+esc(pretty(result.changes||{}))+'</div></div>'}catch(error){openResultModal('⚠️ خطای ویرایش محصول',{ok:false,error:error.message})}finally{busy(button,false)}}}catch(error){openResultModal('⚠️ خطای دریافت جزئیات محصول',{ok:false,error:error.message,recommendations:['شناسه محصول، غرفه و دسترسی توکن را بررسی کنید.']})}}
function destinationBulkBody(remove=false){const ops={};if(remove)ops.delete=true;else{const priceOp=$('destPriceOp').value,priceValue=$('destPriceValue').value.trim();if(priceOp)ops.price={op:priceOp,val:priceValue};if($('destBulkStock').value!=='')ops.stock=Number($('destBulkStock').value);if($('destBulkStatus').value)ops.status=$('destBulkStatus').value;if($('destTitlePrefix').value)ops.titlePrefix=$('destTitlePrefix').value;if($('destTitleSuffix').value)ops.titleSuffix=$('destTitleSuffix').value;if($('destBulkShort').value)ops.shortDescription=$('destBulkShort').value;if($('destBulkDesc').value)ops.description=$('destBulkDesc').value}return{ids:destinationRefs(),ops}}
async function runDestinationBulk(apply=false,remove=false){if(!dest.selected.size)throw Error('ابتدا حداقل یک محصول را انتخاب کنید.');if(dest.selected.size>20)throw Error('در هر نوبت حداکثر ۲۰ محصول قابل انتخاب است.');if(apply&&!confirm((remove?(dest.target==='basalam'?'محصولات انتخاب‌شده بایگانی':'محصولات انتخاب‌شده حذف'):'تغییرات گروهی اعمال')+' شوند؟ این عملیات واقعی است.'))return;const button=remove?(apply?$('destBulkDelete'):$('destBulkDeletePreview')):apply?$('destBulkApply'):$('destBulkPreview'),body=destinationBulkBody(remove);if(apply)body.confirm='APPLY';busy(button,true);try{const d=await api('/api/destination/'+dest.target+'/bulk',{method:'POST',body:JSON.stringify(body)});openResultModal((d.dryRun?'👁 پیش‌نمایش':'✓ نتیجه')+' '+(remove?(dest.target==='basalam'?'بایگانی گروهی':'حذف گروهی'):'ویرایش گروهی'),{...d,raw:d.items,recommendations:d.dryRun?['هیچ تغییری اعمال نشده است؛ سطرهای پاسخ خام را بازبینی و سپس دکمه اعمال را بزنید.']:d.failed?['ردیف‌های دارای error را بررسی و فقط همان موارد را دوباره اجرا کنید.']:['عملیات روی مقصد کامل شد.']});output(d);if(!d.dryRun){dest.selected.clear();await loadDestination(true)}}finally{busy(button,false)}}
async function runExtractionDiagnostic(id){const profile=state.profiles.find(x=>x.id===id);if(profile)activateProfile(id);modalShell('🩺 عیب‌یابی استخراج '+(profile?.name||id),'<div class="dest-loading">در حال دریافت واقعی صفحه و اجرای مرحله‌به‌مرحله pipeline…</div>');try{const d=await api('/api/profiles/'+encodeURIComponent(id)+'/extraction-diagnostic',{method:'POST',body:'{}'}),labels={configuration:'پیکربندی',network:'دریافت شبکه', 'list-extraction':'استخراج فهرست','selector-evidence':'نشانه‌های سلکتور','detail-extraction':'استخراج جزئیات'},stages=(d.stages||[]).map(stage=>{const details={...stage};delete details.name;delete details.ok;delete details.summary;return '<div class="stage-card '+(stage.ok?'ok':'bad')+'"><b>'+(stage.ok?'✓ ':'✗ ')+esc(labels[stage.name]||stage.name)+'</b><p>'+esc(stage.summary||'')+'</p><details><summary>نمایش داده‌های این مرحله</summary><div class="raw-block">'+esc(pretty(details))+'</div></details></div>'}).join(''),recommendations=(d.recommendations||[]).length?'<h3>راهکار پیشنهادی</h3><ul style="font-size:11px;line-height:2">'+d.recommendations.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'';modalShell('🩺 گزارش استخراج واقعی · '+(profile?.name||id),'<div class="result-summary '+(d.ok?'ok':'bad')+'"><b>'+(d.ok?'pipeline واقعی با موفقیت محصول پیدا کرد.':'یک یا چند مرحلهٔ واقعی استخراج ناموفق است.')+'</b><br>محصول پیدا‌شده: '+fa(d.productCount||0)+' · زمان: '+fa(d.durationMs||0)+' میلی‌ثانیه</div><div class="stage-list">'+stages+'</div>'+recommendations+'<h3>نشانی آزمایش‌شده</h3><div class="raw-block">'+esc(d.finalUrl||d.url||'—')+'</div>');output(d);notice(d.ok?'عیب‌یابی استخراج موفق بود.':'عیب‌یابی علت شکست را مشخص کرد.',d.ok?'ok':'error')}catch(error){openResultModal('⚠️ خطای عیب‌یابی استخراج',{ok:false,error:error.message,recommendations:['دسترسی شبکه و آدرس پروفایل را بررسی کنید.']})}}
async function loadProducts(){const id=$('productProfile').value;if(!id){notice('یک پروفایل انتخاب کنید.','error');return}activateProfile(id);const button=$('loadProducts');busy(button,true);try{const q=encodeURIComponent($('productSearch').value.trim()),data=await api('/api/profiles/'+encodeURIComponent(id)+'/products?limit=200&q='+q);$('productCount').textContent=fa(data.total)+' محصول';$('statProducts').textContent=fa(data.products.length);$('productBadge').hidden=!data.total;$('productBadge').textContent=data.total>99?'+۹۹':fa(data.total);$('products').innerHTML=data.products.map(p=>'<article class="product"><div class="thumb">'+(p.image?'<img loading="lazy" src="'+escAttr(p.image)+'" alt="">':'بدون تصویر')+'</div><div class="pbody"><div class="ptitle">'+esc(p.title)+'</div><span class="price">'+fa(p.price)+' تومان</span><div class="pmeta">'+esc(p.sku||p.brand||'')+'</div></div></article>').join('')||'<div class="empty">محصولی یافت نشد.</div>'}catch(error){notice(error.message,'error')}finally{busy(button,false)}}
async function loadJobs(show=true){try{const data=await api('/api/jobs?limit=100');state.jobs=data.jobs;renderJobs();if(show)notice('صف تازه‌سازی شد.')}catch(error){if(show)notice(error.message,'error')}}
function jobEventRows(job,metric){const log=Array.isArray(job.log)?job.log:[],events=metric==='price-changed'?['price-increased','price-decreased']:metric==='successful'?['sync-created','sync-updated']:metric==='processed'?(job.kind==='sync'?['sync-created','sync-updated','failed']:['added','updated','failed']):[metric];return log.filter(row=>row.item&&events.includes(row.event))}
function jobMetricButton(job,metric,label,count,tone=''){return '<button class="job-metric '+tone+'" data-job-metric="'+metric+'" data-id="'+job.id+'">'+label+'<b>'+fa(count)+'</b></button>'}
function jobMetricsHtml(job,compact=false){const count=metric=>jobEventRows(job,metric).length,success=count('successful'),removed=count('removed'),out=count('out-of-stock'),zero=count('zero-price'),price=count('price-changed');let html=jobMetricButton(job,'processed','انجام‌شده',job.processed,'info')+jobMetricButton(job,'added','جدید',job.added,'good')+jobMetricButton(job,'updated','آپدیت',job.updated,'info')+jobMetricButton(job,'failed','خطا',job.failed,'bad');if(job.kind==='sync'||success)html+=jobMetricButton(job,'successful','ارسال موفق',success,'good');if(job.kind==='scrape'&&!compact)html+=jobMetricButton(job,'removed','حذف‌شده',removed,'warn')+jobMetricButton(job,'out-of-stock','اتمام موجودی',out,'warn')+jobMetricButton(job,'zero-price','قیمت صفر',zero,'bad')+jobMetricButton(job,'price-changed','تغییر قیمت',price,'info');return'<div class="job-metrics">'+html+'</div>'}
function miniJobsHtml(kind){const rows=state.jobs.filter(j=>j.kind===kind).slice(0,3);return rows.map(j=>{const active=['queued','running'].includes(j.status),pct=j.total?Math.min(100,Math.round(j.processed/j.total*100)):(j.status==='done'?100:0),target=j.kind==='sync'?' · '+(j.target==='woo'?'ووکامرس':j.target==='basalam'?'باسلام':'هر دو مقصد'):'';return '<div class="mini-job"><div class="mini-job-head"><b>'+(j.kind==='scrape'?'استخراج':'ارسال')+' · '+esc(profileName(j.profileId))+target+'</b><span class="job-status s-'+j.status+'">'+esc(j.status)+'</span></div><small>'+esc(j.phase||'waiting')+' · '+fa(j.processed)+' / '+fa(j.total)+'</small><div class="mini-progress"><i style="width:'+pct+'%"></i></div>'+jobMetricsHtml(j,false)+(active?'<button class="btn btn-red btn-sm" data-job-action="stop" data-id="'+j.id+'" style="margin-top:8px">■ توقف</button>':'')+'</div>'}).join('')||'<div class="empty compact">صف خالی است.</div>'}
function renderJobs(){const active=state.jobs.filter(j=>['queued','running'].includes(j.status));$('jobBadge').hidden=!active.length;$('jobBadge').textContent=fa(active.length);$('statRunning').textContent=fa(active.length);$('statFailed').textContent=fa(state.jobs.filter(j=>j.status==='failed').length);$('jobs').innerHTML=state.jobs.map(j=>{const pct=j.total?Math.min(100,Math.round(j.processed/j.total*100)):0,target=j.kind==='sync'?' · '+(j.target==='woo'?'ووکامرس':j.target==='basalam'?'باسلام':'هر دو مقصد'):'';return '<div class="job"><div class="job-head"><b>'+(j.kind==='scrape'?'استخراج':'ارسال')+' · '+esc(profileName(j.profileId))+target+'</b><span class="job-status s-'+j.status+'">'+esc(j.status)+'</span></div><div class="progress"><div class="bar" style="width:'+pct+'%"></div></div><div style="font-size:10px;color:#94a3b8">مرحله: '+esc(j.phase)+' · '+fa(j.processed)+' / '+fa(j.total)+'</div>'+jobMetricsHtml(j,false)+(active.some(x=>x.id===j.id)?'<button class="btn btn-red btn-sm" data-job-action="stop" data-id="'+j.id+'" style="margin-top:10px">■ توقف</button>':'<div class="menu-actions"><button class="btn btn-orange btn-sm" data-job-action="retry" data-id="'+j.id+'">↻ اجرای دوباره</button><button class="btn btn-red btn-sm" data-job-action="delete" data-id="'+j.id+'">حذف</button></div>')+(j.error?'<div class="logs">'+esc(j.error)+'</div>':'')+'</div>'}).join('')||'<div class="empty">صف خالی است.</div>';renderHomeJobs();if($('destinationJobs'))$('destinationJobs').innerHTML=miniJobsHtml('sync')}
function openJobMetric(id,metric){const job=state.jobs.find(item=>item.id===id);if(!job)return;const labels={processed:'محصولات انجام‌شده',added:'محصولات جدید',updated:'محصولات آپدیت‌شده',failed:'خطاها',removed:'حذف‌شده از مبدأ',"out-of-stock":'اتمام موجودی',"zero-price":'محصولات با قیمت صفر',"price-changed":'محصولات تغییر قیمت یافته',successful:'ارسال‌های موفق'},rows=jobEventRows(job,metric),content=rows.length?'<div class="job-product-list">'+rows.map(row=>{const item=row.item||{},price=item.oldPrice!==undefined&&item.newPrice!==undefined,up=Number(item.delta)>0,priceHtml=price?'<div class="'+(up?'price-up':'price-down')+'"><b>'+fa(item.oldPrice)+' ← '+fa(item.newPrice)+' تومان</b><br>'+(up?'افزایش ':'کاهش ')+fa(Math.abs(item.delta||0))+' تومان · '+fa(Math.abs(item.percent||0))+'٪</div>':'<div style="color:#94a3b8">'+esc(item.shop||item.target||row.message||'')+(item.error?'<br><span class="price-up">'+esc(item.error)+'</span>':'')+'</div>';return'<div class="job-product-row"><div><b>'+esc(item.title||'محصول بدون عنوان')+'</b><br><small style="color:#94a3b8">'+esc(item.sourceKey||'')+(item.url?' · <a href="'+escAttr(item.url)+'" target="_blank" rel="noopener">صفحهٔ مبدأ</a>':'')+'</small></div>'+priceHtml+'</div>'}).join('')+'</div>':'<div class="empty">برای این کار جزئیات محصولی ثبت نشده است. کارهای قدیمی فقط عدد کلی دارند؛ اجرای بعدی فهرست دقیق را ذخیره می‌کند.</div>';modalShell('📦 '+(labels[metric]||'جزئیات صف')+' · '+esc(profileName(job.profileId)),'<div class="result-summary ok">'+fa(rows.length)+' ردیف جزئیات ثبت‌شده</div>'+content)}

