let importAnalysis=null,importSelectedFile=null;
const IMPORT_FIELD_OPTIONS=[['','— نادیده بگیر —'],['title','نام محصول (title)'],['price','قیمت'],['url','آدرس/لینک'],['image','تصویر'],['sku','کد/شناسه کالا'],['brand','برند'],['stock','موجودی'],['weight','وزن'],['category','دسته‌بندی'],['shortDesc','توضیح کوتاه'],['longDesc','توضیحات کامل'],['tags','برچسب‌ها'],['sourceKey','کلید منبع (sourceKey)'],['variations','تنوع‌ها'],['attributes','ویژگی‌ها (نام:مقدار)']];
function importFileMime(file){return /\.xlsx$/i.test(file.name)?'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'text/csv; charset=utf-8'}
function importFileFormat(file){return /\.xlsx$/i.test(file.name)?'xlsx':'csv'}
function setImportDrop(file){const zone=$('importDropZone');if(!zone)return;if(file){zone.classList.add('has-file');zone.querySelector('.import-drop-title').textContent='📎 '+file.name+' — '+(file.size/1024).toFixed(0)+' KB';zone.querySelector('.import-drop-hint').textContent='برای تغییر، دوباره کلیک کنید'}else{zone.classList.remove('has-file');zone.querySelector('.import-drop-title').textContent='فایل را اینجا رها کنید یا کلیک کنید';zone.querySelector('.import-drop-hint').textContent='CSV (UTF-8) یا Excel (.xlsx) — حداکثر ۱۰ مگابایت'}}
async function analyzeImport(){const status=$('importStatusLine'),file=importSelectedFile||($('importFile')&&$('importFile').files[0]);try{if(!file)throw Error('ابتدا یک فایل CSV یا Excel انتخاب کنید.');const id=$('importProfile').value.trim();if(!id)throw Error('ابتدا پروفایل مقصد را انتخاب کنید.');if(status){status.hidden=false;status.textContent='⏳ در حال تحلیل فایل روی سرور…'}const d=await api('/api/import/analyze?format='+importFileFormat(file),{method:'POST',headers:{'content-type':importFileMime(file)},body:file});importAnalysis=d;if(!d.headers.length)throw Error('فایل جدولی قابل خواندن ندارد یا ستون ندارد.');renderImportMapping(d);renderImportPreview(d);renderImportIssues(d);const card=$('importMappingCard'),exec=$('importExecute');if(card)card.hidden=false;if(exec)exec.hidden=false;if(status){status.hidden=false;status.textContent='✅ تحلیل کامل شد — '+fa(d.total)+' ردیف · '+fa(d.headers.length)+' ستون'+(d.priceHint==='rial'?' · ⚠️ به‌نظر می‌رسد قیمت‌ها «ریال» هستند؛ در تنظیمات پیشرفته بررسی کنید.':'')}notice('تحلیل فایل انجام شد؛ نگاشت ستون‌ها را بررسی و سپس «ورود به بانک» را بزنید.','ok');return d}catch(error){if(status){status.hidden=false;status.textContent='❌ '+error.message}notice(error.message,'error');throw error}}
function renderImportMapping(d){const el=$('importMapping'),info=$('importRowsInfo');if(!el)return;if(info)info.textContent=fa(d.total)+' ردیف — '+fa(d.headers.length)+' ستون';el.innerHTML=d.headers.map(header=>{const detected=(d.mapping||[]).find(m=>m.column===header),value=detected?detected.field:'';return '<div class="import-map-cell"><label>'+esc(header||'(بدون نام)')+'</label><select data-import-col="'+escAttr(header)+'">'+IMPORT_FIELD_OPTIONS.map(opt=>'<option value="'+escAttr(opt[0])+'"'+(opt[0]===value?' selected':'')+'>'+esc(opt[1])+'</option>').join('')+'</select>'+(detected&&detected.confidence<1?'<div class="conf">تشخیص خودکار ('+Math.round(detected.confidence*100)+'٪)</div>':'')+'</div>'}).join('')}
function renderImportPreview(d){const head=$('importPreviewHead'),body=$('importPreviewBody');if(!head||!body)return;
  const mappingObj=Object.fromEntries((d.mapping||[]).map(m=>[m.column,m.field]));
  const fieldLabels={title:'نام محصول',price:'قیمت',attributes:'ویژگی‌ها',sku:'کد',stock:'موجودی',category:'دسته',brand:'برند',url:'آدرس',image:'تصویر',weight:'وزن',shortDesc:'توضیح کوتاه',longDesc:'توضیحات',tags:'برچسب‌ها',variations:'تنوع',sourceKey:'کلید'};
  const rows=(d.samples||[]),shown=rows.length;
  // Header: column name + a mapping <select> so the mapping can also be changed here.
  head.innerHTML='<tr><th class="row-num">#</th>'+d.headers.map(h=>{const field=mappingObj[h]||'';return '<th>'+esc(h)+'<select class="head-map-sel" data-head-col="'+escAttr(h)+'">'+IMPORT_FIELD_OPTIONS.map(opt=>'<option value="'+escAttr(opt[0])+'"'+(opt[0]===field?' selected':'')+'>'+esc(opt[1])+'</option>').join('')+'</select></th>'}).join('')+'</tr>';
  body.innerHTML=rows.map((row,index)=>{
    const mapped=Object.fromEntries(d.headers.map(h=>[mappingObj[h]||h,row[h]]));
    const title=String(mapped.title||mapped.name||'').trim();
    const price=normalizeImportPriceClient(String(mapped.price??''),$('importPriceUnit')?.value||'none');
    const issues=[];if(!title)issues.push('بدون نام');if(price===null)issues.push('قیمت نامعتبر');else if(price===0)issues.push('قیمت صفر');
    const attrCols=(d.mapping||[]).filter(m=>m.field==='attributes');
    const attrs=attrCols.map(m=>parseImportAttributesClient(row[m.column],m.column)).flat().filter(Boolean);
    const attrText=attrs.map(g=>g.name+': '+g.values.join('، ')).join('؛ ');
    return '<tr class="preview-row'+(issues.length?' row-issue':'')+'" data-row="'+index+'"><td class="row-num">'+fa(index+1)+'</td>'+d.headers.map(h=>{
      const field=mappingObj[h]||'',raw=row[h]===undefined||row[h]===null?'':String(row[h]);let cell='';
      if(field==='title')cell=title?esc(title.slice(0,90)):'<span class="badge bad">بدون نام</span>';
      else if(field==='price')cell=price===null?'<span class="badge bad">نامعتبر</span>':price===0?'<span class="badge warn">۰</span>':'<b class="price-val">'+fa(price)+'</b>';
      else if(field==='attributes')cell=attrText?'<span class="attr-text">'+esc(attrText.slice(0,110))+'</span>':'<span class="muted">—</span>';
      else if(field==='image')cell=raw?(raw.startsWith('http')||raw.startsWith('data:')?'<span class="badge ok thumb-dot">📷 تصویر</span>':'<span class="badge warn thumb-dot">🖼 مسیر</span>'):'<span class="muted">—</span>';
      else if(field==='url')cell=raw?'<a class="cell-link" href="'+escAttr(raw)+'" target="_blank" rel="noopener noreferrer">'+esc(raw.slice(0,34))+'</a>':'<span class="muted">—</span>';
      else cell=raw?esc(raw.slice(0,60)):'<span class="muted">—</span>';
      return '<td>'+cell+'</td>'}).join('')+'</tr>'}).join('')||'<tr><td colspan="'+(d.headers.length+1)+'" class="empty">ردیفی برای پیش‌نمایش نیست.</td></tr>';
  const info=$('importRowsInfo');if(info&&d.total)info.innerHTML='<span class="th-count">'+fa(d.total)+' ردیف</span>نمایش '+fa(shown)+' ردیف اول · '+fa(d.headers.length)+' ستون · برای جزئیات هر ردیف روی آن کلیک کنید';
}
function openImportRowModal(d,row,index){
  const mappingObj=Object.fromEntries((d.mapping||[]).map(m=>[m.column,m.field]));
  const mapped=Object.fromEntries(d.headers.map(h=>[mappingObj[h]||h,row[h]]));
  const title=String(mapped.title||mapped.name||'').trim();
  const price=normalizeImportPriceClient(String(mapped.price??''),$('importPriceUnit')?.value||'none');
  const attrCols=(d.mapping||[]).filter(m=>m.field==='attributes');
  const attrs=attrCols.map(m=>parseImportAttributesClient(row[m.column],m.column)).flat().filter(Boolean);
  const items=d.headers.map(h=>{const field=mappingObj[h]||'',raw=row[h]===undefined||row[h]===null?'':String(row[h]);let val=raw?esc(raw.slice(0,400)):'<span class="muted">—</span>';
    if(field==='price')val=price===null?'<span class="badge bad">نامعتبر</span>':price===0?'<span class="badge warn">۰</span>':'<b class="price-val">'+fa(price)+'</b>';
    else if(field==='image')val=raw?'<span class="badge ok thumb-dot">📷 تصویر</span>':'<span class="muted">—</span>';
    else if(field==='url'&&raw)val='<a class="cell-link" href="'+escAttr(raw)+'" target="_blank" rel="noopener noreferrer">'+esc(raw.slice(0,120))+'</a>';
    return '<div class="detail-item"><small>'+esc(h||'(بدون نام)')+(field?' — '+esc(fieldLabels[field]||field):'')+'</small><span style="white-space:pre-wrap">'+val+'</span></div>'});
  if(attrs.length)items.push('<div class="detail-item"><small>ویژگی‌ها (استخراج‌شده)</small><span class="attr-text">'+esc(attrs.map(g=>g.name+': '+g.values.join('، ')).join('؛ '))+'</span></div>');
  const issues=[];if(!title)issues.push('بدون نام');if(price===null)issues.push('قیمت نامعتبر');else if(price===0)issues.push('قیمت صفر');
  modalShell('🔍 جزئیات ردیف '+fa(index+1),(issues.length?'<div class="result-summary bad"><b>⚠️ '+esc(issues.join('، '))+'</b></div>':'<div class="result-summary ok"><b>✓ ردیف سالم</b></div>')+'<div class="detail-grid">'+items.join('')+'</div>');
}
function parseImportAttributesClient(value,columnName){const raw=String(value??'').trim();if(!raw)return[];const out=[];const merge=(name,vals)=>{const n=String(name||'').trim(),list=vals.map(v=>String(v||'').trim()).filter(Boolean);if(!n||!list.length)return;const f=out.find(g=>g.name===n);if(f)f.values=[...new Set([...f.values,...list])];else out.push({name:n,values:[...new Set(list)]})};if(raw.startsWith('[')||raw.startsWith('{')){try{const p=JSON.parse(raw);if(Array.isArray(p))for(const item of p){if(item&&typeof item==='object'){const name=String(item.name||'').trim(),values=Array.isArray(item.values)?item.values:item.value!==undefined?[item.value]:item.options;if(name&&values)merge(name,values.map(String))}}else if(p&&typeof p==='object')for(const[name,values]of Object.entries(p))merge(name,Array.isArray(values)?values.map(String):[String(values)]);if(out.length)return out}catch{}}
  const parts=raw.split(/[|;\n]/).map(p=>p.trim()).filter(Boolean);for(const part of parts){const colon=part.search(/[:=]/);if(colon>0){const name=part.slice(0,colon).trim(),values=part.slice(colon+1).split(/[,،/]+/).map(v=>v.trim()).filter(Boolean);if(name&&values.length)merge(name,values)}else{const values=part.split(/[,،/]+/).map(v=>v.trim()).filter(Boolean);if(values.length)merge(columnName||'ویژگی',values)}}return out}
function renderImportIssues(d){const el=$('importIssues');if(!el)return;const chips=[];chips.push('<span class="import-issue ok">✓ '+fa(d.total)+' ردیف</span>');if(d.issues.missingTitle)chips.push('<span class="import-issue bad">بدون نام: '+fa(d.issues.missingTitle)+'</span>');else chips.push('<span class="import-issue ok">نام: کامل</span>');if(d.issues.missingPrice)chips.push('<span class="import-issue warn">بدون قیمت: '+fa(d.issues.missingPrice)+'</span>');if(d.issues.zeroPrice)chips.push('<span class="import-issue warn">قیمت صفر: '+fa(d.issues.zeroPrice)+'</span>');if(d.issues.invalidPrice)chips.push('<span class="import-issue bad">قیمت نامعتبر: '+fa(d.issues.invalidPrice)+'</span>');if(d.priceHint==='rial')chips.push('<span class="import-issue warn">💰 احتمالاً ریال است</span>');el.innerHTML=chips.join('')+(d.issues.checked<d.total?'<span class="import-issue">بررسی '+fa(d.issues.checked)+' ردیف نمونه</span>':'')}
function normalizeImportPriceClient(raw,unit){const text=String(raw||'').trim();if(!text)return 0;let digits=text.replace(/[۰-۹٠-٩]/g,ch=>{const fa='۰۱۲۳۴۵۶۷۸۹'.indexOf(ch);return fa>=0?String(fa):String('٠١٢٣٤٥٦٧٨٩'.indexOf(ch))});digits=digits.replace(/[^\d.,-]/g,'').replace(/\./g,'').replace(/^,+/,'').replace(/,+/g,'');const n=Number(digits);if(!Number.isFinite(n))return null;if(unit==='rial')return Math.round(n/10);if(unit==='multiply10')return Math.round(n*10);return Math.round(n)}
function collectImportMapping(){const map={};document.querySelectorAll('#importMapping select[data-import-col]').forEach(sel=>{const field=sel.value;if(field)map[sel.dataset.importCol]=field});return map}
async function executeImport(){const status=$('importStatusLine'),file=importSelectedFile||($('importFile')&&$('importFile').files[0]);try{if(!file)throw Error('فایلی انتخاب نشده است.');const id=$('importProfile').value.trim();if(!id)throw Error('پروفایل مقصد را انتخاب کنید.');if(!importAnalysis)await analyzeImport();const opts={mapping:collectImportMapping(),skipMissingTitle:($('importSkipNoTitle')?.value||'skip')!=='keep',skipMissingPrice:($('importSkipNoPrice')?.value||'keep')==='skip',priceUnit:$('importPriceUnit')?.value||'none',defaultStock:Number($('importDefaultStock')?.value||0),dedupe:$('importDedupe')?.value||'none'};if(status){status.hidden=false;status.textContent='⏳ در حال ورود محصولات به بانک… (تا چند ثانیه)'}const d=await api('/api/profiles/'+encodeURIComponent(id)+'/import?format='+importFileFormat(file)+'&opts='+encodeURIComponent(JSON.stringify(opts))+'&name='+encodeURIComponent(file.name),{method:'POST',headers:{'content-type':importFileMime(file)},body:file});if(status){status.hidden=false;status.textContent='✅ '+fa(d.imported)+' محصول وارد شد · خطا '+fa(d.failed)+' · ردشده '+fa(d.skipped||0)}notice('درون‌ریزی تمام شد.',d.failed||d.skipped?'error':'ok');openResultModal('📥 گزارش درون‌ریزی',{...d,summary:fa(d.imported)+' محصول از '+fa(d.rows)+' ردیف وارد پروفایل شد.'+(d.skipped?' ('+fa(d.skipped)+' ردیف طبق تنظیمات رد شد)':''),recommendations:d.failed?['جزئیات خطاهای هر ردیف را در پاسخ خام ببینید.']:['اکنون محصولات آمادهٔ بازبینی یا ارسال به مقصد هستند.']});loadImportHistory();return d}catch(error){if(status){status.hidden=false;status.textContent='❌ '+error.message}notice(error.message,'error');throw error}}
function downloadImportTemplate(){const headers=['نام محصول','قیمت','ویژگی‌ها','آدرس','تصویر','کد محصول','برند','موجودی','وزن','دسته‌بندی','توضیح کوتاه','توضیحات کامل','برچسب‌ها'],sample=['عطر گل محمدی ۵۰ میل','450000','رنگ:قرمز، آبی|سایز:M، L','https://example.com/p/1','https://example.com/img/1.jpg','SKU-001','برند نمونه','10','50','عطر و ادکلن','عطر گرم و ماندگار','توضیحات کامل…','جدید'],csv='\uFEFF'+[headers.join(','),sample.join(',')].join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='scraper4-import-template.csv';a.click();URL.revokeObjectURL(a.href);notice('قالب نمونه CSV دانلود شد — ستون «ویژگی‌ها» به‌صورت نام:مقدار پر می‌شود.','ok')}
async function loadImportHistory(){const el=$('importHistoryList');if(!el)return;try{const d=await api('/api/import/history'),items=d.items||[];el.innerHTML=items.length?items.slice().reverse().map(h=>'<div class="visual-row"><div class="visual-row-head"><b>'+esc(h.fileName||'درون‌ریزی')+'</b><span class="chip">'+esc(h.format)+' — '+fa(h.rows)+' ردیف</span></div><div style="font-size:10px;color:#94a3b8;margin:4px 0">واردشده: <b style="color:#86efac">'+fa(h.imported)+'</b> · خطا: <b style="color:#fca5a5">'+fa(h.failed)+'</b>'+(h.skipped?' · ردشده: '+fa(h.skipped):'')+(h.wooStatus?' · وضعیت ووکامرس: '+esc(h.wooStatus):'')+'</div><div style="font-size:9px;color:#64748b">'+esc(h.at||'')+'</div></div>').join(''):'<div class="empty">هنوز درون‌ریزی‌ای ثبت نشده است.</div>'}catch(error){el.innerHTML='<div class="empty">خطا در دریافت تاریخچه</div>'}}

